<?php
$expected = array(
  56 => array( 'hash' => 'c8b307d1039b92e359a3ccdeb77c4b2d19219a567594467342708b9f4699bc41', 'phone' => '1-800-350-550', 'website' => 'https://www.kkl.org.il/travel/trips/290971/' ),
  169 => array( 'hash' => '34582c6f88b1619908b420d7caa5449652fa82544fe1c41fd94e8170f932fb67', 'phone' => '*3639', 'website' => 'https://www.parks.org.il/reserve-park/%D7%A9%D7%9E%D7%95%D7%A8%D7%AA-%D7%98%D7%91%D7%A2-%D7%94%D7%A8-%D7%9E%D7%99%D7%A8%D7%95%D7%9F/' ),
  171 => array( 'hash' => '286cb6ebf4218b9ef13143a8699a224d6649562fe55d9402fd721d0a3c5bbb36', 'phone' => '*3639', 'website' => 'https://www.parks.org.il/reserve-park/%D7%A9%D7%9E%D7%95%D7%A8%D7%AA-%D7%98%D7%91%D7%A2-%D7%A0%D7%97%D7%9C-%D7%9B%D7%96%D7%99%D7%91/' ),
);
$new_content = array(
  56 => base64_decode( '' ),
  169 => base64_decode( '' ),
  171 => base64_decode( '' ),
);
foreach ( $expected as $id => $state ) {
  $current = (string) get_post_field( 'post_content', $id );
  $data = GoNorth_Place_Data::get( $id );
  if ( hash( 'sha256', $current ) !== $state['hash'] ) {
    throw new RuntimeException( "Content changed for {$id}; refusing update." );
  }
  if ( (string) $data['phone'] !== $state['phone'] || (string) $data['website'] !== $state['website'] || '' !== (string) $data['business_hours'] || '' !== (string) $data['price_type'] || '' !== (string) $data['practical_checked_at'] ) {
    throw new RuntimeException( "Practical data changed for {$id}; refusing update." );
  }
}
foreach ( $expected as $id => $state ) {
  $result = wp_update_post( array( 'ID' => $id, 'post_content' => $new_content[ $id ] ), true );
  if ( is_wp_error( $result ) ) {
    throw new RuntimeException( $result->get_error_message() );
  }
  $updated = GoNorth_Place_Data::update( $id, array(), true, false );
  if ( is_wp_error( $updated ) ) {
    throw new RuntimeException( $updated->get_error_message() );
  }
  clean_post_cache( $id );
}
$out = array();
foreach ( array_keys( $expected ) as $id ) {
  $data = GoNorth_Place_Data::get( $id );
  $out[] = array(
    'id' => $id,
    'title' => get_the_title( $id ),
    'url' => get_permalink( $id ),
    'content_hash' => hash( 'sha256', (string) get_post_field( 'post_content', $id ) ),
    'phone' => $data['phone'],
    'website' => $data['website'],
    'business_hours' => $data['business_hours'],
    'price_type' => $data['price_type'],
    'practical_checked_at' => $data['practical_checked_at'],
  );
}
wp_cache_flush();
echo wp_json_encode( $out, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES );
